802	    {
803	        State& s = *m_State;
804	        if (s.Ended) return false;
805	        const EStep::CancellationScope scope(&s.Config.Cancelled);
806	        const auto cancelled = [&s] { return s.Config.Cancelled && s.Config.Cancelled(); };
807	        const auto stage = [&s](const Stage value) { if (s.Config.StageObserver) s.Config.StageObserver(value); };
808	        if (cancelled())
809	        {
810	            s.Fail(Status::Cancelled);
811	            return false;
812	        }
813	        double nll = 0.0, matched = 0.0;
814	        stage(Stage::ExpectationStep);
815	        if (s.Config.Method == Variant::Bayesian) s.UpdateBayesianWeights();
816	        ++s.Revision;
817	        const bool expected = s.ExpectationStep(nll, matched);
818	        // A cancelled E-step skipped chunks: its statistics are incomplete, whatever it returned.
819	        if (cancelled())
820	        {
821	            s.Fail(Status::Cancelled);
822	            return false;
823	        }
824	        if (!expected)
825	        {
826	            s.Fail(Status::NumericalFailure);
827	            return false;
828	        }
829	        const double objective = nll + s.Coherence();
830	        s.LastNll = nll;
831	        s.LastMatched = matched;
832	        const bool converged = s.HasPreviousObjective &&
833	            std::abs(s.LastObjective - objective) <= s.Config.Tolerance * std::abs(objective);
834	        s.LastObjective = objective;
835	        s.HasPreviousObjective = true;
836	        if (converged)
