846	        {
847	        case Variant::Rigid: status = s.RigidStep(matched); break;
848	        case Variant::Affine: status = s.AffineStep(matched); break;
849	        case Variant::Nonrigid: status = s.NonrigidStep(matched); break;
850	        case Variant::Bayesian: status = s.BayesianStep(matched); break;
